INSERT INTO "evaluation_results" VALUES('d752ef89-9ffb-4e73-8090-f11c23f45053','4f3854ab-9522-472e-9bd3-f2d0c7215f2c','c6b9e73f-cf23-44f5-af55-048bfd5a3551','347d2dc4-5f95-4d25-9820-ad134609759d','fafc080f-c2ac-4e4e-9815-bf87bfc3807f','succeeded','{}','',17018,1062959,1762343202117,NULL,1762343202179,'The AI agent successfully read the provided URL and then created a recipe for ''Seafood Pasta''. However, the generated recipe''s serving size was 4, which does not match the ''Servings: 6'' specified in the input information, hence failing the ''大致相同'' (roughly the same) criterion.',0);
INSERT INTO "evaluation_results" VALUES('9e47bc26-6fdd-4975-82fa-6fecf3ced9d4','4f3854ab-9522-472e-9bd3-f2d0c7215f2c','257f1b16-0655-4f27-b688-025c97955f55','69edba74-7439-4c76-832f-0bf92b8ba951','0044ceb0-3e62-4acd-94c1-6832dd12d0a0','succeeded','{}','',6999,2336013,1762344465155,NULL,1762344465341,'AI Agent创建了一个名为“Pay utility bills”的任务，截止日期为2025年11月10日，并设置了一个提前一天（即11月9日）的提醒。这个任务的日期在当前日期2025年11月5日之后，符合所有评估标准。',1);
